INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_ssh-bruteforce', 'soc', 'triage', 'fresher', 'An alert fires: several failed SSH logins from one IP, then a successful one. What do you do first?', 'Scope before acting. Which account succeeded, is the source internal or external, and does that account normally sign in from there. Then look at what the session did afterwards, especially sudo or any new key added. The failure that sinks candidates is calling it a brute force and closing it without reading what happened after the success.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ssh-bruteforce_f1', 'q_soc_fresher_ssh-bruteforce', 1, 'The success was on a different account from the failures. Does that change your read?', 'It makes it worse. Failures on one account and a success on another points at spraying across accounts, or at an attacker who already had working credentials while the failures were noise. The next question is what else that account touched and whether there were quiet successes you never alerted on.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ssh-bruteforce_f2', 'q_soc_fresher_ssh-bruteforce', 2, 'The account belongs to a developer who says it was him. How do you verify?', 'Do not take the word alone, and do not treat doubting him as an accusation. Match the source address against his known locations and VPN logs, check the client version, and line the timing up against his working hours. Even if he was working, three failures on somebody else''s account still needs explaining.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_ids-vs-ips', 'soc', 'detection', 'fresher', 'What is the difference between an IDS and an IPS?', 'An IDS observes and alerts; an IPS sits inline and can drop. The difference that matters operationally is consequence: a false positive on an IDS is noise, a false positive on an IPS is an outage. That is why signatures go out in detect mode first and get promoted to block only once the noise is understood.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ids-vs-ips_f1', 'q_soc_fresher_ids-vs-ips', 1, 'Your IPS is dropping legitimate traffic. What do you change first?', 'Move the offending signature to alert-only. Not the whole policy, and not the device. That stops the damage while keeping visibility, and gives you the traffic to decide whether to tune the rule, exempt the source, or fix the application that is tripping it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_ids-vs-ips_f2', 'q_soc_fresher_ids-vs-ips', 2, 'Who signs off on that change, and what goes in the ticket?', 'Whoever owns the control, with the application owner informed. The ticket records which rule, what traffic it matched, what the temporary state is, when it will be reviewed, and who approved it. A tuning change with no review date quietly becomes a permanent blind spot.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_phishing-report', 'soc', 'phishing', 'fresher', 'A user reports a phishing email. Walk me through what you do.', 'Preserve the original with full headers before anything else. Pull sender, reply-to, originating address, authentication results, links and attachments, and detonate anything live in a sandbox rather than on your own machine. Then find out who else received it and whether anyone interacted.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_phishing-report_f1', 'q_soc_fresher_phishing-report', 1, 'The user already clicked. What changes?', 'It stops being analysis and becomes containment. Find out what the page asked for and whether credentials went in. If they did, reset the password and invalidate active sessions and tokens, not just the password, then check for mailbox rules created after the click, which is the usual first move after a mailbox compromise.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_phishing-report_f2', 'q_soc_fresher_phishing-report', 2, 'How do you find everyone else who got it?', 'Search the mail platform by sender, originating address and URL, not just the exact subject, because the campaign varies it. Then separate delivered from opened from clicked, purge what is left in mailboxes, and report those three numbers, because that is what the business will ask for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_url-to-render', 'soc', 'fundamentals', 'fresher', 'You type a URL and press enter. Walk me through what happens, and tell me where you would look if it broke.', 'DNS resolution, TCP connection, TLS handshake, HTTP request, response, render. The interviewer is not testing recall; they are testing whether you can hang investigation on the model. A strong answer names what fails at each step and what you would check to prove it, rather than reciting the sequence.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_url-to-render_f1', 'q_soc_fresher_url-to-render', 1, 'It resolves but times out. Which layer do you suspect?', 'Resolution worked, so the problem is after DNS: routing, a firewall silently dropping rather than rejecting, or a dead service. A reject gives you a fast refusal; a timeout usually means something is dropping packets on purpose. Trace the path and test the port directly rather than reloading the browser.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_url-to-render_f2', 'q_soc_fresher_url-to-render', 2, 'It loads but the browser warns about the certificate. What are the possibilities, in order?', 'Most likely the dull ones: expired certificate, wrong hostname, or an incomplete chain. Then an inspection proxy injecting its own certificate, which is normal on a corporate network. Interception by someone you did not invite is real but last, and you confirm it by comparing the issuer with what you expect, not by guessing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_unknown-alert', 'soc', 'process', 'fresher', 'You are on L1 and an alert type you have never seen before lands in the queue. Walk me through it.', 'The honest answer is a method, not knowledge. Read what the rule is actually looking for, find the raw events behind it, establish whether the behaviour is normal for that host or account, and check whether it has fired before and how it was closed. Escalate with what you found, not with the alert forwarded untouched.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_unknown-alert_f1', 'q_soc_fresher_unknown-alert', 1, 'Nobody senior is online and it looks serious. What do you do?', 'Act on the reversible things and escalate the rest. Collect and preserve evidence, follow whatever containment the runbook already authorises for L1, and page according to the escalation path rather than waiting for a shift change. Err towards waking someone: an unnecessary call costs far less than a missed hour.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_unknown-alert_f2', 'q_soc_fresher_unknown-alert', 2, 'It turns out to be benign. Does anything still need doing?', 'Yes, or you will spend the rest of the year reading it. Write down why it was benign in terms specific enough for the next analyst, and either tune the rule or record that it stays noisy for a reason. An alert that keeps arriving with no decision attached is how a queue stops being read at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_threat-vuln-risk', 'soc', 'fundamentals', 'fresher', 'What is the difference between a vulnerability, a threat and a risk?', 'A vulnerability is a weakness, a threat is something that could exploit it, and risk is the combination weighed by likelihood and impact. The useful version is practical: an unpatched server is a vulnerability, a group that exploits that software is a threat, and the risk depends on whether that server is exposed and what it holds.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_threat-vuln-risk_f1', 'q_soc_fresher_threat-vuln-risk', 1, 'Two servers have the same critical CVE. One is in the DMZ, one is on an isolated test VLAN. Same risk?', 'No, and this is exactly why severity alone does not prioritise anything. Same vulnerability, very different exposure and impact. Patch the exposed one first and say so in those terms, because that is the sentence that gets you taken seriously by people who own uptime.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_threat-vuln-risk_f2', 'q_soc_fresher_threat-vuln-risk', 2, 'The test VLAN turns out to have a route to production. Now what?', 'The risk rating was wrong because the network diagram was wrong, which is the normal case. Re-rate it, patch it, and then raise the route itself as the bigger finding: an isolated segment that is not isolated invalidates every other risk decision that assumed it was.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_what-siem-does', 'soc', 'tooling', 'fresher', 'What is a SIEM actually doing, and what is it not doing?', 'It collects logs from many sources, normalises them into a common shape, correlates across them, and raises alerts on rules you wrote. What it is not doing is understanding your environment or finding things nobody asked it to look for. A SIEM with no tuned rules and no log sources that matter is an expensive search bar.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_what-siem-does_f1', 'q_soc_fresher_what-siem-does', 1, 'Leadership asks why the SIEM missed something. How do you answer?', 'Find out which of three things failed before answering: the log never arrived, the log arrived but no rule looked for that behaviour, or a rule fired and nobody acted. They need completely different fixes, and saying "the SIEM missed it" hides which one it was. Answer with the specific gap and what closes it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_what-siem-does_f2', 'q_soc_fresher_what-siem-does', 2, 'Which log sources would you fight for first, with a limited budget?', 'Identity and endpoint, in that order. Authentication tells you who did what, and endpoint telemetry tells you what actually ran. Firewall and proxy logs are high volume and easy to buy but answer fewer questions on their own. Say what you would cut, not just what you would add, because that is the real question.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_beaconing-host', 'soc', 'triage', 'fresher', 'A laptop is reaching out to the same external address every sixty seconds, give or take a few. What do you check?', 'Regular intervals with small jitter mean automation, not a person. Establish which process is making the connection, what the destination is and how long it has been running, and whether other hosts do the same. Beaconing is a shape, and plenty of legitimate software has that shape too.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_beaconing-host_f1', 'q_soc_fresher_beaconing-host', 1, 'The destination is a well-known cloud provider. Does that clear it?', 'No. Hosting on a reputable provider is cheap and extremely common for command and control, precisely because the domain looks harmless and often cannot be blocked wholesale. Judge it on the process making the call and what it sends, not on who owns the address range.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_beaconing-host_f2', 'q_soc_fresher_beaconing-host', 2, 'It turns out to be a legitimate agent nobody documented. What do you do with that?', 'Close the alert and then fix the real problem, which is that an unknown agent was running on a managed laptop. Get it into the asset and software inventory, and raise that the inventory is incomplete. The next unexplained beacon should be answerable in minutes, not hours.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_fresher_why-soc', 'soc', 'behavioural', 'fresher', 'Why security, and why a SOC role specifically?', 'The weak answer is "I am passionate about cybersecurity". The strong one is concrete: something you actually did, what it taught you, and why the SOC in particular rather than security in general. Mentioning that you want the volume and pattern exposure a SOC gives early in a career shows you understand what the job is.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_why-soc_f1', 'q_soc_fresher_why-soc', 1, 'Where do you want to be in three years? Say pentesting, and watch what happens.', 'Be honest, because the usual lie is obvious and they have heard it. If you want to move towards hunting, detection engineering or offensive work, say so and say what the SOC gives you on the way there. Managers plan around real ambitions. They lose people who pretended not to have any.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_fresher_why-soc_f2', 'q_soc_fresher_why-soc', 2, 'This role is on rotating shifts including nights. Still interested?', 'Answer the question that is really being asked, which is whether you will quit in four months. Say plainly whether nights work for you. Agreeing to something you cannot sustain is worse for you than for them, and the ones who handle this honestly in the room are the ones who last.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_signed-binary', 'soc', 'endpoint', 'mid', 'Your EDR flags a signed binary behaving unusually. How do you triage it?', 'A valid signature says who built it, not that this execution is safe. Look at the behaviour chain: parent process, command line, network destinations, files written, persistence created. Signed system tools get abused for living-off-the-land execution precisely because reputation scoring waves them through.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_signed-binary_f1', 'q_soc_mid_signed-binary', 1, 'The signature is valid and the vendor is well known. Still suspicious?', 'Yes, if the behaviour does not match what that binary exists to do. A known-good tool launched by an unusual parent, with arguments that fetch a remote payload, is a standard abuse pattern. The question is whether this execution is expected on this host, not whether the file is malicious in general.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_signed-binary_f2', 'q_soc_mid_signed-binary', 2, 'You decide to contain. What exactly, and what do you tell the business?', 'Isolate at the network level while keeping your own access, rather than powering off and losing memory. Block the destination at the egress point. Then tell the business which host, what the user can no longer do, what you need from them, and when you will next update them. Vague updates are what turn an incident into a political problem.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_rule-tuning', 'soc', 'tuning', 'mid', 'How do you tune a noisy detection rule without going blind to the thing it was built for?', 'Start from what the rule is meant to catch, then measure what it is actually matching. Narrow on the attribute that separates benign from malicious, usually a specific process, account or destination, rather than lowering severity or widening the window. Record the exclusion and the reason, so the next analyst can see the gap you accepted.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_rule-tuning_f1', 'q_soc_mid_rule-tuning', 1, 'The noise comes from one application the business will not change. Now what?', 'Scope the exclusion as tightly as the application allows: that service account, on those hosts, to those destinations. Add a narrower compensating rule that would still fire if the excluded pattern were abused, and write down the residual risk so it is a decision on record rather than a silent hole.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_rule-tuning_f2', 'q_soc_mid_rule-tuning', 2, 'Six months later, how do you know the tuning is still right?', 'Review exclusions on a schedule and test them. Confirm the application still behaves the way the exclusion assumes, and validate that the rule still fires on the original behaviour using an atomic test. An exclusion nobody has revisited is a control nobody can vouch for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_coverage-real', 'soc', 'detection', 'mid', 'How do you know your detection coverage is real and not just a long list of rules?', 'Map detections to attacker behaviours rather than counting rules, then test them. A framework like ATT&CK gives you the map; atomic tests tell you whether the rule actually fires in your environment with your log sources. Coverage you have never fired is a claim, not a control.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_coverage-real_f1', 'q_soc_mid_coverage-real', 1, 'Your map shows green across the board. Do you believe it?', 'No, and saying so is the right answer. A green map usually means coverage was recorded when the rule was written, not verified since. Log sources get dropped, agents fall off hosts, and parsers break quietly. Treat the map as a to-test list rather than a report card.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_coverage-real_f2', 'q_soc_mid_coverage-real', 2, 'You find a technique you genuinely cannot detect. What do you do with it?', 'Write it down as a known gap with what it would take to close it, which is usually a log source or a licence rather than cleverness. Then look for a compensating detection one step earlier or later in the chain. A documented gap with an owner beats an undocumented one that someone assumes is covered.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_incident-walkthrough', 'soc', 'behavioural', 'mid', 'Walk me through an incident you actually handled, start to finish.', 'Pick one you can tell honestly, including what went wrong. Structure it: how it was detected, what you first thought, what changed your mind, what you contained, and what the organisation changed afterwards. The part interviewers listen hardest for is the moment your first theory was wrong and how you noticed.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_incident-walkthrough_f1', 'q_soc_mid_incident-walkthrough', 1, 'What would you do differently?', 'Have a real answer. "Nothing" reads as either inexperience or no reflection. Name something specific, such as containing before fully scoping and losing visibility, or not getting the business on a call early enough, and say what you changed afterwards so it did not repeat.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_incident-walkthrough_f2', 'q_soc_mid_incident-walkthrough', 2, 'Who did you escalate to, and when?', 'They are checking whether you understand that escalation is a decision with a cost both ways. Name the trigger you used, not just the person. Candidates who escalate everything are as hard to staff around as candidates who escalate nothing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_siem-cost', 'soc', 'tooling', 'mid', 'Your SIEM ingest cost has doubled and you have been told to cut it. What goes?', 'Start from which logs have ever been used in a detection or an investigation, because the bill usually hides a few enormous, useless sources. Cut volume before cutting sources: filter noisy event types, sample what is only ever used in aggregate, and move long-tail data to cheaper storage you can still search when it matters.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_siem-cost_f1', 'q_soc_mid_siem-cost', 1, 'Finance wants you to drop endpoint logs because they are the biggest line.', 'Push back with what breaks, in their language: name the detections that stop working and the investigations that become impossible. Then offer the alternative, which is usually filtering at the agent and shortening hot retention rather than dropping the source. Agreeing quietly and losing the capability silently is the failure mode.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_siem-cost_f2', 'q_soc_mid_siem-cost', 2, 'Six months later nobody remembers what was cut. How do you prevent that?', 'Record the cut as a risk decision with an owner and a review date, not as a config change in a ticket. Put the affected detections in the same record. When the next incident hits a blind spot, the question becomes who accepted it and when, which is a fair conversation, rather than why security missed it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_shift-handover', 'soc', 'process', 'mid', 'How do you hand over a live incident at shift change?', 'Written, not verbal, and structured: what is known, what is believed but unconfirmed, what has been done including anything you changed, what is pending and who owns it, and the next decision point. The common failure is handing over conclusions without the evidence, so the next shift cannot tell what to re-check.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_shift-handover_f1', 'q_soc_mid_shift-handover', 1, 'The incoming analyst disagrees with your read. What should happen?', 'Good, that is the handover working. Separate what is observed from what is inferred and let them re-examine the inference against the evidence. The handover note should make that possible without you in the room. If disagreement feels like a challenge rather than a check, the process is broken.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_shift-handover_f2', 'q_soc_mid_shift-handover', 2, 'What do you deliberately leave out?', 'Speculation dressed as fact, and the running commentary. Keep the timeline, the evidence and the open decisions. A handover that includes every thought anyone had during the shift is one nobody reads, which is the same as no handover at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_soc_mid_closed-wrongly', 'soc', 'process', 'mid', 'An analyst on your team closed a true positive as benign. How do you handle it?', 'Handle the incident first, then the cause. Reopen, scope what was missed and how long it ran. Then look at why it was closable: was the evidence genuinely ambiguous, was the queue too deep to read properly, or was the runbook wrong. One analyst making one call is almost never the real finding.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_closed-wrongly_f1', 'q_soc_mid_closed-wrongly', 1, 'It turns out the runbook told them to close it. Now what?', 'Then the analyst did their job and the runbook is the defect. Fix it, and say so publicly to the team, because the alternative teaches everyone that following the process is risky. That lesson costs far more than this incident did.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_soc_mid_closed-wrongly_f2', 'q_soc_mid_closed-wrongly', 2, 'How do you catch this class of mistake earlier next time?', 'Sample closed alerts, not just open ones. A small weekly review of a random handful of benign closures catches both bad runbooks and queue pressure, and it does it without singling anyone out. Reviewing only what blew up means you only ever learn from the ones that blew up.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_tcp-handshake', 'network', 'tcp', 'fresher', 'Explain the TCP three-way handshake.', 'The client sends SYN with its initial sequence number, the server replies SYN-ACK acknowledging it and offering its own, the client replies ACK. The point is that both sides agree on sequence numbers and both prove they can receive, which is what makes blind spoofing hard. Say why it exists, not just the three words.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tcp-handshake_f1', 'q_network_fresher_tcp-handshake', 1, 'You see thousands of SYNs with no completing ACKs. What is happening?', 'Half-open connections, so either a SYN flood or a scan. A flood is trying to exhaust the backlog; a scan is looking for open ports and usually comes with RSTs. Tell them apart by volume, how spread the sources are, and whether the destination ports vary or stay fixed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tcp-handshake_f2', 'q_network_fresher_tcp-handshake', 2, 'How would you confirm it, and what would you actually do?', 'Confirm with a capture and the host''s own connection-state counters rather than trusting the alert. Mitigation is SYN cookies, rate limiting at the edge, and upstream filtering once the volume exceeds your link. If it is a scan rather than a flood, the answer is blocking and investigating the source, not tuning the stack.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_stateful-firewall', 'network', 'firewalls', 'fresher', 'What is the difference between a stateful and a stateless firewall?', 'A stateless firewall judges each packet in isolation. A stateful one tracks connections, so return traffic for an established session is allowed without a matching inbound rule. Stateful is why you do not have to write a rule for every ephemeral port on the way back.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_stateful-firewall_f1', 'q_network_fresher_stateful-firewall', 1, 'Which goes at the perimeter, and why?', 'Stateful, because the perimeter is exactly where you need to tell solicited return traffic from unsolicited inbound traffic. A stateless filter there either blocks legitimate replies or forces rules so broad they stop meaning anything.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_stateful-firewall_f2', 'q_network_fresher_stateful-firewall', 2, 'What does stateful inspection cost you that stateless does not?', 'Memory and a finite connection table, which is itself a target: fill the table and the device starts dropping or fails open. It costs per-connection processing at high throughput, and it makes failover harder, because state has to be synchronised or every session breaks on cutover.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_dns-resolution', 'network', 'dns', 'fresher', 'Walk me through how a name gets resolved, and tell me where you would tamper with it if you were an attacker.', 'Browser cache, OS cache, configured resolver, then recursion from root to TLD to authoritative, with the answer cached at each hop by TTL. An attacker goes for whichever step is softest: the host file, the resolver setting, a registrar account, or cache poisoning. The caching is the interesting part, because it is what makes a bad answer stick.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_dns-resolution_f1', 'q_network_fresher_dns-resolution', 1, 'A user says one site is wrong but everyone else is fine. Where do you look?', 'Start local, because that is where the difference is. Host file, the resolver that machine is actually using, and any proxy or VPN in the path. Compare their answer against a known-good resolver from the same network, which tells you in one step whether it is the machine or the network.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_dns-resolution_f2', 'q_network_fresher_dns-resolution', 2, 'What does DNSSEC actually protect against, and what does it not?', 'It gives you integrity: the answer came from the zone owner and was not altered. It does not give you confidentiality, so the query is still visible, and it says nothing about whether the domain is trustworthy. A signed answer from a malicious domain is still perfectly valid.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_nat-investigation', 'network', 'addressing', 'fresher', 'What is NAT, and why does it make your job harder?', 'NAT rewrites addresses so many internal hosts share one public address. The investigative cost is that an external log showing your public address identifies the company, not the machine. Without NAT translation logs correlated by source port and exact timestamp, an abuse report is unactionable.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_nat-investigation_f1', 'q_network_fresher_nat-investigation', 1, 'You get an abuse report naming your public IP at 14:32. What do you need to find the host?', 'The translation logs for that window, plus the source port and ideally the destination, because the public address alone maps to hundreds of machines. If those logs are not kept, say so plainly: the honest answer is that you cannot identify the host, and the finding is the missing log.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_nat-investigation_f2', 'q_network_fresher_nat-investigation', 2, 'CGNAT at the ISP sits in front of you too. What does that change?', 'The same problem one layer up, and now it is someone else''s logs. It also means an external address in your own logs may be shared by many unrelated subscribers, so blocking or attributing on that address alone hits bystanders. Weight address-based indicators accordingly.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_tls-what-it-gives', 'network', 'crypto', 'fresher', 'HTTP versus HTTPS: what exactly does TLS give you, and what does it not?', 'Confidentiality in transit, integrity so content cannot be altered undetected, and authentication of the server through its certificate. What it does not give you is a safe site, a safe endpoint, or hidden metadata: the destination address and the hostname in SNI are still visible, and the data is plaintext again the moment it arrives.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tls-what-it-gives_f1', 'q_network_fresher_tls-what-it-gives', 1, 'A phishing site has a valid padlock. Explain that to a user.', 'The padlock means the connection to that site is private, not that the site is honest. Certificates are free and issued in minutes to anyone who controls a domain, including attackers. Tell users to read the domain, not the lock, and stop teaching the lock as a safety signal.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_tls-what-it-gives_f2', 'q_network_fresher_tls-what-it-gives', 2, 'Your company inspects TLS at the proxy. What are you giving up?', 'You break end-to-end encryption on purpose, so the proxy becomes a single place where all plaintext exists and a very high-value target. You also create legal and privacy obligations around what is inspected, and you break certificate pinning in some apps. It is a real trade, and the honest answer names both sides.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_fresher_vpn-protects', 'network', 'remote-access', 'fresher', 'What is a VPN actually protecting against?', 'It protects traffic in transit across a network you do not trust, and for corporate use it puts the device inside a network boundary. That is it. It does not make the endpoint safe, it does not make you anonymous to the sites you visit, and a compromised laptop on a VPN is a compromised laptop with a route into the office.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vpn-protects_f1', 'q_network_fresher_vpn-protects', 1, 'Everyone is remote. Is a VPN still the right model?', 'It is one model, and it has a known weakness: once you are in, you are inside. The alternative is per-application access with identity and device posture checked on every request, which removes the all-or-nothing boundary. Name the trade rather than reciting a buzzword, because most organisations end up running both for years.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_fresher_vpn-protects_f2', 'q_network_fresher_vpn-protects', 2, 'Split tunnelling: good or bad?', 'It depends on what you give up. Split tunnelling saves bandwidth and keeps the concentrator alive, but it means the device''s general internet traffic never passes your inspection, so you lose that visibility. If the endpoint has its own telemetry you can live with it. If the VPN was your only visibility, you cannot.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_segmentation', 'network', 'segmentation', 'mid', 'You are asked to segment a flat corporate network. Where do you start?', 'With what talks to what, not with the diagram you wish you had. Collect flow data long enough to cover monthly jobs, group assets by function and sensitivity, then design the fewest zones that separate what must not reach each other. Enforce in monitor mode before you enforce for real.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_segmentation_f1', 'q_network_mid_segmentation', 1, 'Finance says segmentation will break their reporting tool.', 'Get the actual flows rather than the claim: source, destination, port, frequency. It is usually a handful you can allow explicitly. If the tool genuinely needs broad access, that becomes a documented exception with a compensating control and a named owner, not a reason to abandon the zone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_segmentation_f2', 'q_network_mid_segmentation', 2, 'How do you prove the segmentation holds?', 'Test from inside each zone: attempt the connections that should fail and confirm they fail at the enforcement point, not just that nobody complained. Keep it as a repeatable check, because rule sprawl quietly re-flattens a network inside a year and nobody notices until an incident.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_dns-exfil', 'network', 'dns', 'mid', 'You see repeated TXT queries to a domain registered three days ago. What is your read?', 'That shape fits DNS tunnelling or beaconing: TXT carries more than A records, and a newly registered domain is a standard indicator. Look at query volume, subdomain entropy, how regular the timing is, and which host is asking. Clockwork intervals mean a process, not a person.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_dns-exfil_f1', 'q_network_mid_dns-exfil', 1, 'How do you tell exfiltration from a misconfigured tool?', 'Content and direction. Tunnelling shows long, high-entropy subdomain labels and sustained two-way volume; a misbehaving security or telemetry agent queries a vendor domain with predictable labels. Identifying the process on the host settles it faster than any amount of packet analysis.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_dns-exfil_f2', 'q_network_mid_dns-exfil', 2, 'What do you block, and what breaks if you are wrong?', 'Sinkhole that domain, not TXT records and not the resolver. If you are wrong you break one tool and hear about it in minutes, which is recoverable. Blocking at the resolver breaks name resolution for everyone, which is an outage you caused while chasing a maybe.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_egress-filtering', 'network', 'architecture', 'mid', 'Design egress filtering for an office of three hundred people. Where do you start and where do you stop?', 'Start by learning what actually leaves, then default-deny the protocols nobody should be using outbound directly, such as DNS to anything but your resolvers, SMTP, and arbitrary high ports. Force web traffic through a proxy you can see. Stop short of a full allowlist of destinations unless the business is one that can live with it.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_egress-filtering_f1', 'q_network_mid_egress-filtering', 1, 'Engineering says default-deny will break their builds hourly.', 'They are probably right, and that is an argument about sequencing, not direction. Run in log-only mode long enough to capture the real destination set, give them a documented path to request additions with a fast turnaround, and enforce per segment rather than everywhere at once. Enforcement without a working exception process always gets rolled back.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_egress-filtering_f2', 'q_network_mid_egress-filtering', 2, 'What does this actually buy you against a determined attacker?', 'Not prevention. It buys constraint and signal: it pushes them onto the few channels you watch closely, and it turns a silent exfiltration into a blocked connection that fires an alert. Claiming it stops a capable attacker is the answer that loses credibility in the room.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_lateral-movement', 'network', 'detection', 'mid', 'You cannot segment the network this quarter. How do you detect lateral movement anyway?', 'Watch for the behaviours segmentation would have blocked: workstation-to-workstation SMB or RDP, which almost never happens legitimately, authentication from one account across many hosts in a short window, and admin tools running where no admin works. Detection cannot replace segmentation, but it shortens the time you are blind.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_lateral-movement_f1', 'q_network_mid_lateral-movement', 1, 'Your IT team does exactly that all day with remote support tools.', 'Then baseline them and alert on the exception: the named support accounts from their jump hosts are normal, and the same behaviour from a finance laptop is not. The work is identifying the legitimate pattern precisely enough that everything outside it is interesting, which is most of the effort in any detection like this.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_lateral-movement_f2', 'q_network_mid_lateral-movement', 2, 'What is the single highest-value log source here?', 'Authentication, specifically where each account signs in and from what. Lateral movement is an identity story before it is a network story, and account-to-host mapping catches techniques that never generate distinctive network traffic at all.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_network_mid_vpn-saturated', 'network', 'troubleshooting', 'mid', 'The VPN concentrator is saturated and people cannot work. Diagnose it.', 'Separate the three candidates before touching anything: more users than capacity, one user or process consuming the link, or the device itself degraded. Check concurrent sessions against the licensed and tested limit, top talkers by volume, and CPU on the box. Then say which it is rather than restarting and hoping.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_vpn-saturated_f1', 'q_network_mid_vpn-saturated', 1, 'It is one host pushing enormous volume. Is that an incident?', 'It might be a backup client, a sync tool, or exfiltration, and the destination tells you which in about a minute. Treat it as a performance issue until the destination says otherwise, but do look, because "the network was slow" is how a number of real exfiltrations were first noticed and then dismissed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_network_mid_vpn-saturated_f2', 'q_network_mid_vpn-saturated', 2, 'Leadership wants it fixed now. What do you do first?', 'Restore service with the least destructive lever: throttle or disconnect the one offending session rather than resetting the device and dropping three hundred people. Then say what the permanent fix is, capacity or split tunnelling or both, and what it costs. Fix now, design later, but do not let later never come.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_owasp-most-common', 'pentest', 'web', 'fresher', 'Which OWASP Top 10 risk do you see most often in real applications, and why that one?', 'Broken access control, because it is a logic problem rather than a pattern a scanner matches. Authentication comes from a framework; authorisation is written per endpoint by hand, so one missing ownership check in one route is enough. Answer with why it recurs, not just the name.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_owasp-most-common_f1', 'q_pentest_fresher_owasp-most-common', 1, 'Show me how you would test for it on a login-protected endpoint.', 'Authenticate as a low-privilege user, capture a request that references an object you own, then replay it with another identifier while keeping your own session. If someone else''s data comes back, that is the finding. Repeat for write operations, because read and write are often guarded differently.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_owasp-most-common_f2', 'q_pentest_fresher_owasp-most-common', 2, 'The developer says the WAF blocks it.', 'Demonstrate it through the WAF, from the path a real user takes. A WAF matches patterns; an authorisation flaw is a valid, well-formed request the application should have refused. If it still works end to end, the argument is settled without a debate.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_scan-vs-test', 'pentest', 'scope', 'fresher', 'What is the difference between a vulnerability scan and a penetration test?', 'A scan enumerates known issues against signatures and reports what might be exploitable. A test proves impact by chaining findings the way an attacker would. Put in client terms: a scan tells you what is present, a test tells you what it is worth.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_scan-vs-test_f1', 'q_pentest_fresher_scan-vs-test', 1, 'A client wants a pentest but the budget fits a scan. What do you tell them?', 'Say plainly that a scan will not answer the question they are asking, then offer the honest middle: a scan plus manual validation of the highest-impact findings, scoped to the part of the estate that carries real risk. Selling a scan as a test is how firms lose clients at the next breach.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_scan-vs-test_f2', 'q_pentest_fresher_scan-vs-test', 2, 'What goes in the report that a scanner cannot produce?', 'The chain and the consequence: how three mediums combined into access to a named dataset, what an attacker holds at the end, and what to fix first given their constraints. A scanner produces severity. A tester produces a prioritised story somebody can act on.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_sqli-confirm', 'pentest', 'web', 'fresher', 'What is SQL injection, and how would you confirm it on a live client system without breaking anything?', 'Untrusted input reaching a query as code rather than data. Confirm with the least invasive proof available: a boolean or timing difference that shows the query is being altered, not a payload that dumps or modifies data. On production you prove controllability and stop, then describe the impact rather than demonstrating it.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_sqli-confirm_f1', 'q_pentest_fresher_sqli-confirm', 1, 'Blind injection, no output at all. How do you prove it?', 'Inference. A conditional that changes the response, or a timing primitive that makes the server pause when a condition is true. Keep the proof small and reproducible, because a report that says "probably injectable" gets closed, and one with a repeatable condition does not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_sqli-confirm_f2', 'q_pentest_fresher_sqli-confirm', 2, 'The fix they propose is escaping quotes. Is that enough?', 'No. Escaping is a filter and filters get bypassed through encoding, numeric contexts and places quoting does not apply, such as an ORDER BY clause. The fix is parameterised queries so input can never be parsed as code, with validation and least-privilege database accounts as depth, not as the fix.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_encode-hash-encrypt', 'pentest', 'crypto', 'fresher', 'Encoding, hashing and encryption: what is the difference and when is each the wrong choice?', 'Encoding changes representation and reverses with no secret, so it is not protection. Hashing is one way and is for verifying, not storing recoverable data. Encryption is reversible with a key and is for data you need back. The interview failure is calling base64 encryption, and the real-world failure is hashing something you later need to read.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_encode-hash-encrypt_f1', 'q_pentest_fresher_encode-hash-encrypt', 1, 'You find passwords stored as unsalted MD5. How bad, and what do you write?', 'Bad, and the reason is not that MD5 is "broken" in the abstract: it is fast and unsalted, so a commodity GPU plus a rainbow table recovers most of those passwords in minutes. Write it as credential compromise with reuse risk across other services, not as a cryptography nitpick.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_encode-hash-encrypt_f2', 'q_pentest_fresher_encode-hash-encrypt', 2, 'They ask what to use instead.', 'A slow, salted password hash designed for the job: Argon2id, scrypt or bcrypt, with parameters tuned to their hardware. Say that migration happens on next login rather than in a big bang, since you cannot reverse the old hashes. Give the migration path, because that is the part that stalls these fixes.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_default-creds', 'pentest', 'engagement', 'fresher', 'You find default credentials on an admin panel during an engagement. What now?', 'Confirm they work, capture the evidence, and stop. Do not start exploring with those credentials unless the scope explicitly permits it. Then judge the impact: what that panel controls decides whether this is a routine finding or a call you make today rather than at the readout.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_default-creds_f1', 'q_pentest_fresher_default-creds', 1, 'The panel manages their payment flow. Same handling?', 'No. That is an out-of-band notification the same day, through the escalation path agreed before the engagement started. You still do not go further in. The value you add is speed and clarity about what is exposed, not proving how far you could have gone.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_default-creds_f2', 'q_pentest_fresher_default-creds', 2, 'You log in and find someone else is already there.', 'Stop, preserve what you saw, change nothing, and escalate immediately as a live incident rather than a finding. Your own actions need to be clearly separable from theirs in their timeline, which is another reason to have been logging your own activity from the first minute.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_fresher_learning-changed', 'pentest', 'behavioural', 'fresher', 'What is the last thing you learned that changed how you test?', 'They are checking whether you actually practise or just collect certificates. Name something specific and recent, what you believed before, and what you do differently now. "I learned to read the application''s own authorisation code before testing it, because guessing object ids was wasting days" beats any list of tools.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_learning-changed_f1', 'q_pentest_fresher_learning-changed', 1, 'Where do you practise?', 'Be concrete and honest: labs, deliberately vulnerable applications, CTFs, your own builds, a bug bounty programme. Say what you did, not what you have an account on. Claiming bounty experience that turns into zero submissions is a short conversation and a memorable one.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_fresher_learning-changed_f2', 'q_pentest_fresher_learning-changed', 2, 'What are you bad at?', 'Answer it properly. Naming a real gap and what you are doing about it reads as someone who can be trusted on scope. A polished non-answer like "I care too much about quality" tells the interviewer you will also sound confident about findings you do not understand.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_shell-next', 'pentest', 'engagement', 'mid', 'You get a shell on a web server during an engagement. What do you do next?', 'Before anything else, confirm the host is in scope and record the time, the path in and what you ran, because that record is what makes the finding defensible. Then establish where you are: user context, host role, what it can reach. Collect what proves impact rather than expanding access for its own sake.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_shell-next_f1', 'q_pentest_mid_shell-next', 1, 'The scope says web application only.', 'Then you may already be at or past the boundary. Stop, document the access as the finding, and get written confirmation before touching the host further. Impact is already proven; carrying on without authorisation turns a strong finding into a contract problem.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_shell-next_f2', 'q_pentest_mid_shell-next', 2, 'You find evidence someone else was already in.', 'Stop testing and notify immediately through the agreed escalation path, because it is now a live incident rather than a test. Preserve what you saw and change nothing. Your activity log matters more than ever, because their responders need to separate you from the intruder.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_severity-call', 'pentest', 'reporting', 'mid', 'How do you decide what to report as critical?', 'Reachable impact, not CVSS alone. What does an attacker get, who can reach it, and what does pulling it off require. An unauthenticated path to customer data is critical; the same bug behind an admin login on an internal segment usually is not. State the reasoning so the rating can be argued with.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_severity-call_f1', 'q_pentest_mid_severity-call', 1, 'The client disagrees with your severity.', 'Ask what they know that you do not, because they often do: a compensating control, a boundary, data that is not what it looks like. If it changes the exposure, adjust and say why. If it does not, keep the rating and record their position in the report rather than quietly lowering it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_severity-call_f2', 'q_pentest_mid_severity-call', 2, 'What makes a finding actionable rather than just alarming?', 'A reproduction a developer can follow, the exact location in code or configuration, the fix stated in their stack rather than in general terms, and a way to verify it worked. Without those, a critical sits in a backlog for a year and everyone blames each other.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_undocumented-api', 'pentest', 'api', 'mid', 'You are handed an API with no documentation and two weeks. How do you approach it?', 'Build the surface map first: proxy the client application to enumerate real endpoints, look for a spec file or schema the app fetches, and check for predictable patterns and old versions left routable. Then establish the authorisation model, because that is where the findings are, and test object access systematically rather than endpoint by endpoint.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_undocumented-api_f1', 'q_pentest_mid_undocumented-api', 1, 'Where are the findings usually, in your experience?', 'Object-level authorisation and forgotten versions. The mobile client often talks to an older, looser endpoint that the web app no longer uses and nobody retired. Mass assignment is the other recurring one: fields the client never sends but the server will happily accept, such as a role or an account id.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_undocumented-api_f2', 'q_pentest_mid_undocumented-api', 2, 'Rate limiting blocks your enumeration. What do you do?', 'Tell the client and agree an allowance or a test window rather than quietly working around a control in production. Working around it can look identical to an attack in their logs, and it also means you never report that rate limiting worked, which was itself worth knowing.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_prod-testing', 'pentest', 'scope', 'mid', 'A client asks you to test production during business hours. What do you negotiate before saying yes?', 'A named contact reachable throughout, an agreed stop condition and who can call it, a window for anything with outage potential, confirmation that backups exist and have been tested, and what is explicitly out of bounds such as denial of service or destructive payloads. Get it in writing and timestamp your own activity.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_prod-testing_f1', 'q_pentest_mid_prod-testing', 1, 'Mid-test, a service goes down. Was it you?', 'Say what you were doing at that moment, immediately, whether or not you think you caused it. Hand over your activity log and help them rule you in or out fast. Going quiet to avoid blame is the single fastest way to lose a client, and it usually comes out anyway.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_prod-testing_f2', 'q_pentest_mid_prod-testing', 2, 'They refuse to give you a stop condition. Do you proceed?', 'Push once, explaining that the stop condition protects them more than you, and if it still is not forthcoming, record the refusal in writing and set a conservative one yourself. Testing production with nobody authorised to stop you is how a test becomes an incident with your name on it.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_ad-approach', 'pentest', 'infrastructure', 'mid', 'Walk me through how you would approach an Active Directory environment.', 'Enumerate before you touch anything: users, groups, computers, trusts, delegation and service accounts, which is almost all readable by any authenticated user. Then look for the structural weaknesses rather than exploits: over-privileged service accounts, unconstrained delegation, Kerberoastable accounts with weak passwords, and paths to Domain Admin that nobody intended.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ad-approach_f1', 'q_pentest_mid_ad-approach', 1, 'What do you check before running anything noisy?', 'Whether they have an EDR and whether the engagement is meant to be detected. If it is a purple exercise, noisy is the point and you coordinate. If it is a stealth test, you pace yourself and avoid the tooling their product signatures. Either way you agree it first rather than finding out from their SOC.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_ad-approach_f2', 'q_pentest_mid_ad-approach', 2, 'You get Domain Admin on day two. Now what?', 'Stop and report, rather than spending the rest of the engagement enjoying it. Then, with their agreement, use the remaining time on what actually helps: the paths that got you there, which of them are cheapest to cut, and what their detection did or did not see along the way.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_pentest_mid_nothing-critical', 'pentest', 'reporting', 'mid', 'Two weeks, and you found nothing critical. What goes in the report?', 'What you tested, how, and what that coverage means, so "nothing critical" is a measured result rather than an absence of effort. Include the lower-severity findings honestly, note the controls that genuinely held and why, and name what you could not reach. A clean report with stated coverage is a legitimate and useful outcome.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_nothing-critical_f1', 'q_pentest_mid_nothing-critical', 1, 'The client says they paid for findings and feels short-changed.', 'Reframe what they bought: evidence about their security posture, not a guaranteed quota of bugs. Show the coverage, and point out that inflating mediums into highs to fill pages is exactly what makes reports useless. Then offer the harder follow-up, such as an assumed-breach scenario, which usually does find something.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_pentest_mid_nothing-critical_f2', 'q_pentest_mid_nothing-critical', 2, 'Your colleague suggests upgrading a few mediums to look better.', 'No, and the reason is practical as well as ethical. Inflated severities train the client to ignore your ratings, so the real critical you find next year gets the same shrug. The value of the rating is that it is believed.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_shared-responsibility', 'cloud', 'fundamentals', 'fresher', 'Explain the shared responsibility model.', 'The provider secures the infrastructure the service runs on; the customer secures what they put in it and how they configure it. The line moves by service type, with managed services taking more of the stack, but identity, access and data configuration stay with the customer in every model.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_shared-responsibility_f1', 'q_cloud_fresher_shared-responsibility', 1, 'Who is responsible for a storage bucket left public?', 'The customer. The provider supplies the controls and increasingly defaults them to private, but the configuration is the customer''s. Nearly every public-bucket incident is a decision somebody made, not a provider failure.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_shared-responsibility_f2', 'q_cloud_fresher_shared-responsibility', 2, 'Name two things people assume the provider handles but it does not.', 'Backups and retention for managed data stores, which are usually opt-in and the customer''s to configure and actually test. And logging: control-plane and data-plane logs often need enabling and paying for, and if nobody turned them on there is no investigation after an incident.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_public-bucket', 'cloud', 'storage', 'fresher', 'A storage bucket is publicly readable. Walk me through the fix.', 'Establish exposure first: what is in it, for how long, and whether access logs show reads from outside. Then remove public access at the account level rather than object by object. Only after that work out how it happened, because the same mechanism has usually produced others you have not found yet.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-bucket_f1', 'q_cloud_fresher_public-bucket', 1, 'It serves a static website that genuinely must stay public.', 'Separate what must be public from what must not: one bucket holding only published assets, everything else moved out. Serve it through a CDN with the origin locked to the CDN rather than exposing the bucket, and keep account-level blocks on every other bucket.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_public-bucket_f2', 'q_cloud_fresher_public-bucket', 2, 'How do you stop the next one?', 'Enforcement, not a reminder: account-level public access blocks, a policy that refuses to create public buckets, and a check in the pipeline so it fails before it ships. Then alert on changes to that configuration, because a control is only as good as the notice you get when someone turns it off.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_iam-basics', 'cloud', 'iam', 'fresher', 'What is cloud IAM, and how is it different from a username and a password?', 'It is policy-based authorisation over every API call, for people and for workloads. The difference is granularity and reach: a policy says which identity may take which action on which resource under which conditions, and machines get identities too. A control-plane permission can be far more dangerous than a login, because it rewrites the environment.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_iam-basics_f1', 'q_cloud_fresher_iam-basics', 1, 'Which is more dangerous, a leaked user password or a leaked access key?', 'Usually the key. It carries whatever the identity can do, it works from anywhere without a browser, it does not prompt for a second factor, and keys rarely expire. A password often sits behind MFA and conditional access, while a key quietly works until somebody revokes it.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_iam-basics_f2', 'q_cloud_fresher_iam-basics', 2, 'What does an identity policy not protect you from?', 'Anything done with legitimate permissions, which is most of what goes wrong. A correctly scoped identity used by the wrong person looks exactly like normal activity, which is why least privilege narrows the blast radius but logging and anomaly detection are what notice.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_security-groups', 'cloud', 'network', 'fresher', 'What does a cloud security group actually do, and what does it not?', 'It is a stateful virtual firewall attached to an instance or interface, allowing traffic by port, protocol and source. It does not inspect content, it does not stop anything already running on the host, and on most platforms it cannot express a deny rule, only an absence of allow.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_security-groups_f1', 'q_cloud_fresher_security-groups', 1, 'You find one with 0.0.0.0/0 on port 22. Is that always a finding?', 'Practically always, but check before calling it, because the fix depends on why. Sometimes it is a jump host nobody cleaned up after; sometimes a real administrative path that should be going through a bastion or a managed session service. The finding is the open path, the recommendation depends on the reason.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_security-groups_f2', 'q_cloud_fresher_security-groups', 2, 'They say it is fine because the instance has no public IP.', 'Then verify it, because that changes the exposure. A rule that is broad but unreachable is lower priority, not a non-issue: the next change that attaches a public address or a load balancer makes it live, with nobody re-reading the rule. Narrow it anyway and say why.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_fresher_first-three-cloud', 'cloud', 'strategy', 'fresher', 'A company is moving to cloud. Name the three things you would secure first, and defend the order.', 'Identity, then logging, then network exposure. Identity because the control plane is the new perimeter and a compromised admin identity is total loss. Logging second because without it you cannot investigate anything, including whether the first item already failed. Exposure third because it is the one you can keep fixing after the fact.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-three-cloud_f1', 'q_cloud_fresher_first-three-cloud', 1, 'Why logging before fixing open ports?', 'Because a missing control can be closed next week, but a missing log is gone for good. Turn on control-plane logging on day one and you can reconstruct what happened during the messy migration. Leave it until later and the whole early period is permanently unexaminable.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_fresher_first-three-cloud_f2', 'q_cloud_fresher_first-three-cloud', 2, 'Leadership says that is too slow. What do you drop?', 'Nothing on that list, but you can shrink it: MFA on privileged identities rather than a full identity redesign, logging on at default settings rather than a tuned pipeline, and public exposure only on internet-facing accounts. Offer a smaller version with a date rather than agreeing to skip a layer.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_secrets-handling', 'cloud', 'secrets', 'mid', 'How do you handle secrets in a cloud application?', 'In a managed secret store, injected at runtime, never in the repository, the image, or environment variables baked at build. Access scoped by identity, reads logged, rotation automated. Where the platform supports workload identity, use it and delete the long-lived credential entirely, because the best secret is the one that does not exist.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secrets-handling_f1', 'q_cloud_mid_secrets-handling', 1, 'A developer committed a key to a public repository. What is your first hour?', 'Rotate first, investigate second. Revoke immediately, because removing the commit does not remove it from forks, caches or anyone who scraped it within seconds. Then pull the audit log for everything that key did from the moment it was pushed. The repository history and the conversation with the developer come after.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secrets-handling_f2', 'q_cloud_mid_secrets-handling', 2, 'How do you know it was not used before you rotated?', 'The audit log filtered by that credential, from push to revocation: unfamiliar addresses, unusual regions, enumeration patterns, changes to identity or logging configuration. If logging was not on for that service, say so plainly. You cannot prove a negative, and the honest answer is that you do not know.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_wildcard-iam', 'cloud', 'iam', 'mid', 'An IAM role has wildcard permissions. How do you fix it without breaking production?', 'Do not guess a replacement policy. Determine what the role actually uses from access logs over a period long enough to include monthly jobs, build least privilege from observed calls, then run it in a mode that reports denials before enforcing. Narrow in stages, not in one change at the end of a sprint.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_wildcard-iam_f1', 'q_cloud_mid_wildcard-iam', 1, 'Nobody knows what the role uses. How do you find out?', 'Query the control-plane audit log for calls made by that role, grouped by service and action, over at least a full reporting cycle. Most providers also expose last-accessed data per service, which hands you the unused surface immediately. Use both: one shows what is used, the other shows what safely is not.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_wildcard-iam_f2', 'q_cloud_mid_wildcard-iam', 2, 'How do you stop it drifting back to wildcards?', 'Policy as code with review, an organisation-level guardrail that refuses wildcard actions on sensitive services, and an alert on policy changes. Drift happens at 2am during an outage, so the control has to be a refusal at deploy time rather than a quarterly audit that finds it months later.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_cloud-incident', 'cloud', 'incident-response', 'mid', 'You suspect a compromise in a cloud account. How is the investigation different from an on-premises one?', 'The control plane is both the crime scene and the toolkit. Your primary evidence is the API audit log rather than disk, and the attacker''s most valuable moves are configuration changes: new identities, new keys, policy edits, logging disabled. You can also snapshot and isolate instantly, which is a real advantage if you use it before you start poking.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-incident_f1', 'q_cloud_mid_cloud-incident', 1, 'What do you preserve first, and how?', 'The audit log, exported out of the account to somewhere the attacker''s identity cannot reach, because an attacker with control-plane access can stop or delete logging. Then snapshot affected volumes and capture instance metadata. Preservation comes before eradication: rebuilding first destroys the only account of what happened.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_cloud-incident_f2', 'q_cloud_mid_cloud-incident', 2, 'The attacker created a new access key on an existing role. What else do you check?', 'Everything that key touched, and then everything else they may have planted: other new keys and identities, trust policy edits that let an outside account assume a role, new regions suddenly in use, and changes to logging or alerting. Revoking one key and declaring victory is the standard mistake.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_container-root', 'cloud', 'containers', 'mid', 'A container is running as root. How bad is it, and what do you do?', 'On its own it is a weakness, not a breach: root in the container is not root on the host unless something else gives way. It matters because it removes a layer, so a code execution bug becomes a much better position, and it combines badly with a privileged flag, a mounted socket or a host path. Judge it with what is next to it.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_container-root_f1', 'q_cloud_mid_container-root', 1, 'It also mounts the container runtime socket. Now how bad?', 'Now it is effectively host compromise, because that socket lets you start a new container with the host filesystem mounted. That combination is one of the most reliable escapes there is. This stops being a hardening item and becomes something you fix this week, with the nodes it ran on treated as suspect.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_container-root_f2', 'q_cloud_mid_container-root', 2, 'The team says the image will not run as non-root.', 'Usually it is file ownership or a low port, and both have standard fixes: adjust ownership in the build, or bind higher and map the port. Ask them to show what fails rather than accepting the claim. If it genuinely cannot change, it needs isolation, a user namespace and a documented exception, not a shrug.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_cloud_mid_secure-cicd', 'cloud', 'pipeline', 'mid', 'How do you secure a CI/CD pipeline, and why is it worth the effort?', 'Because the pipeline deploys to production, so compromising it beats compromising production. Secure it as a production system: short-lived credentials from workload identity rather than stored keys, no secrets in logs, pinned third-party actions, review required on the pipeline definition itself, and separate credentials per environment.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secure-cicd_f1', 'q_cloud_mid_secure-cicd', 1, 'What is the most commonly missed one?', 'The pipeline definition being editable by anyone who can push, which means a branch can rewrite how production is deployed. The other is a workflow that runs on pull requests from forks with access to real secrets, which hands credentials to anyone on the internet who opens a PR.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_cloud_mid_secure-cicd_f2', 'q_cloud_mid_secure-cicd', 2, 'How would you detect a compromised pipeline?', 'Alert on the pipeline''s own identity doing something outside its pattern: deploying from an unusual branch, touching resources it never touches, or running at an odd hour. Also watch for edits to the pipeline definition outside the normal review path. The build identity is usually highly privileged and almost never monitored.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_policy-standard-procedure', 'grc', 'documents', 'fresher', 'What is the difference between a policy, a standard and a procedure?', 'A policy states intent and is approved by leadership. A standard makes it measurable: the specific requirement a thing must meet. A procedure is the steps someone follows to meet it. Policies change rarely, standards change with technology, procedures change with tooling.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_policy-standard-procedure_f1', 'q_grc_fresher_policy-standard-procedure', 1, 'An auditor asks for evidence that a policy is followed. What do you show?', 'Not the policy. Output from the control: configuration exports, ticket records, access review sign-offs, log samples spanning the audit period. Evidence is what the system produced while nobody was watching, not a document describing what ought to happen.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_policy-standard-procedure_f2', 'q_grc_fresher_policy-standard-procedure', 2, 'The evidence does not exist.', 'Say so, rather than assembling it afterwards, which is how a finding becomes a fraud problem. Record it as a gap, start generating the evidence now, and give a remediation date. Auditors handle known gaps with a plan every day. They handle fabricated evidence very differently.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_risk-register', 'grc', 'risk', 'fresher', 'What does a risk register do, and what makes a bad one?', 'It records the risks the organisation has decided to track, each with an owner, a rating, a treatment decision and a review date. A bad one is a list of vulnerabilities with no owner, no decision and no date, which makes it an inventory nobody acts on rather than a tool for allocating attention.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_risk-register_f1', 'q_grc_fresher_risk-register', 1, 'A risk has been "in progress" for two years.', 'Treat the status as false and force a decision. Either it is genuinely being treated, in which case it needs a plan with dates, or the organisation has accepted it, in which case say so explicitly with a named accepting owner. A permanent in-progress entry is an unmade decision hiding as work.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_risk-register_f2', 'q_grc_fresher_risk-register', 2, 'Who should own a risk, security or the business?', 'The function that carries the consequence, because they are the ones who can accept it or fund the fix. Security owns the assessment, the recommendation and the follow-up. When security owns the risk itself, acceptance becomes invisible and nothing ever competes with revenue for budget.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_dpdp-basics', 'grc', 'privacy', 'fresher', 'What is India''s Digital Personal Data Protection Act, and who does it apply to?', 'It governs the processing of digital personal data of people in India, and it reaches organisations outside India that process such data to offer goods or services here. It works on consent and stated purpose, puts duties on the data fiduciary to secure data and report breaches, and gives people rights over their own data. Be clear it is principles and duties, not a technical checklist.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_dpdp-basics_f1', 'q_grc_fresher_dpdp-basics', 1, 'Your company collects phone numbers for delivery updates and later uses them for marketing. Any problem?', 'Yes. Consent is tied to a stated purpose, so a new purpose needs fresh consent rather than a clause buried in the original notice. The practical fix is separating consent at collection and holding a record of what was agreed to and when, because the record is what you have to produce later.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_dpdp-basics_f2', 'q_grc_fresher_dpdp-basics', 2, 'How is that different from GDPR in practice?', 'Same direction, different detail, and the honest answer says you would check the text rather than assuming equivalence. The shapes differ on lawful bases, on how children''s data is handled, and on the regulator and penalty structure. A team that assumes their GDPR programme covers DPDP ends up with gaps it never looked for.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_audit-vs-assessment', 'grc', 'assurance', 'fresher', 'What is the difference between an audit and an assessment?', 'An audit tests against a defined standard and produces a formal opinion, usually by an independent party, with evidence requirements and consequences. An assessment is advisory: it tells you where you stand and what to improve, with no pass or fail. Confusing them in front of a client is a quick way to lose credibility.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_audit-vs-assessment_f1', 'q_grc_fresher_audit-vs-assessment', 1, 'Internal audit asks you to help them prepare for an external audit. Any issue?', 'It depends how far it goes. Helping them understand requirements and find evidence is normal. Writing the evidence they will then test, or testing your own work, destroys the independence the audit exists for. Name the line and say who should do which part.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_audit-vs-assessment_f2', 'q_grc_fresher_audit-vs-assessment', 2, 'The external auditor raises a finding you disagree with.', 'Ask what evidence and what clause it rests on, because often it is a scoping misunderstanding you can clear up with one document. If it stands, accept it and fix it. If it genuinely does not, there is a management response process for exactly this. Arguing informally and leaving it unrecorded helps nobody.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_least-privilege-practice', 'grc', 'controls', 'fresher', 'What does least privilege mean in practice, not in theory?', 'That access is granted for a defined need, scoped to it, and removed when the need ends. The practical work is the removal: joiners get access easily everywhere, movers accumulate it, and leavers get missed. A programme that only controls granting is not doing least privilege, it is doing paperwork at the front door.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_least-privilege-practice_f1', 'q_grc_fresher_least-privilege-practice', 1, 'How would you find out whether it is actually happening?', 'Sample. Take ten people who changed roles in the last year and check whether their old access went away. Take five leavers and check every system, not just the directory. The gap between the policy and that sample is the real state, and it is usually a surprise to leadership.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_least-privilege-practice_f2', 'q_grc_fresher_least-privilege-practice', 2, 'Access reviews come back fully approved every quarter. Believable?', 'No. A review where managers approve everything in one click is a signature, not a control. The fix is making the review smaller and more specific, showing what the access actually permits in plain terms, and requiring a reason for keeping anything unused for ninety days.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_fresher_owner-refuses', 'grc', 'behavioural', 'fresher', 'A business owner refuses a control you have recommended. What do you do?', 'Find out why, because the reason is usually cost, timing or a workflow you did not know about, and all three are negotiable. Offer a smaller version or a compensating control. If they still refuse, write it up as an accepted risk with their name on it and a review date. Then move on without sulking.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_owner-refuses_f1', 'q_grc_fresher_owner-refuses', 1, 'They refuse to sign the acceptance too.', 'Then escalate, calmly and in writing, to whoever owns the risk above them. Unsigned acceptance is not refusal of the control, it is refusal of accountability for it, and that is a different and more serious problem. Record what was recommended, what was declined, and when you escalated.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_fresher_owner-refuses_f2', 'q_grc_fresher_owner-refuses', 2, 'Six months later it causes an incident. How do you handle the conversation?', 'Without a told-you-so, which buys nothing and costs the relationship you need for the next control. Produce the record, keep the focus on fixing it now, and let the decision trail speak. The organisations that learn from this are the ones where raising it was not treated as blame.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_iso-six-months', 'grc', 'certification', 'mid', 'You are asked to get the company ISO 27001 certified in six months. What is your first move?', 'Define the scope, because everything follows from it: which entity, which locations, which systems, which data. Then run a gap assessment against the controls in that scope, which usually finds more already happening in practice but undocumented than leadership expects.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_iso-six-months_f1', 'q_grc_mid_iso-six-months', 1, 'Leadership wants certification without changing how teams work.', 'Say plainly that certification audits evidence of operating controls, so if nothing changes there is nothing to evidence. Then make it tractable: scope tightly to the part of the business that needs the certificate commercially, rather than diluting controls across the whole company to keep everyone comfortable.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_iso-six-months_f2', 'q_grc_mid_iso-six-months', 2, 'Where do first-time certifications actually fail?', 'Not on the controls, on the management system. Risk assessment done once and never revisited, internal audit that did not happen, management review with no record, corrective actions left open. Those are the clauses auditors check first and the ones teams dismiss as paperwork.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_third-party-risk', 'grc', 'vendors', 'mid', 'How do you run third-party risk assessment that is not just a questionnaire nobody reads?', 'Tier vendors by what they can actually reach: data, network access, business criticality. Spend the effort on the top tier and let the long tail be light. Ask for evidence rather than self-attestation where it matters, and put the answers into the contract, because a questionnaire with no contractual teeth changes nothing.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_third-party-risk_f1', 'q_grc_mid_third-party-risk', 1, 'A critical vendor refuses to share their audit report.', 'Find out whether it is confidentiality or absence, because those are different problems. Confidentiality is solvable with an NDA or a summary. If the report does not exist, that is the finding, and the decision moves up to whoever is willing to accept depending on that vendor without assurance.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_third-party-risk_f2', 'q_grc_mid_third-party-risk', 2, 'What do you do between assessments?', 'Watch for the things that change without telling you: breach disclosures, ownership changes, certificate lapses, and your own usage growing past what was assessed. Annual assessment with nothing in between means your view of a vendor is on average six months out of date.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_after-breach', 'grc', 'regulatory', 'mid', 'Your company has had a breach. What does the regulator ask for, and what will you wish you had?', 'What happened, when you knew, what data and how many people, what you did, and how you are preventing recurrence. What you will wish you had is a timeline supported by evidence rather than recollection, and proof that your controls were operating before the incident, not just documented.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_after-breach_f1', 'q_grc_mid_after-breach', 1, 'Your detection timeline has a four-day gap nobody can explain.', 'Report the gap as a gap. An honest unexplained window is survivable; a confident timeline that later turns out to be wrong is not, because it recasts everything else you said as unreliable. Say what you know, what you cannot establish, and why.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_after-breach_f2', 'q_grc_mid_after-breach', 2, 'Legal wants to delay notification while the investigation continues.', 'There is a real tension and it is not yours to resolve alone, but notification clocks generally start on becoming aware, not on finishing the investigation. Your job is to make sure the decision is made knowingly, with the deadline and the facts in front of the people accountable, and recorded.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_measure-programme', 'grc', 'metrics', 'mid', 'How do you measure whether a security programme is actually working?', 'Pick measures tied to outcomes and to how fast you respond, not to activity. Time to detect and time to contain, coverage of critical assets by the controls that matter, how long high findings stay open, and how much of your estate you can actually see. Counting blocked attacks or training completions measures effort, not effect.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_measure-programme_f1', 'q_grc_mid_measure-programme', 1, 'The board wants a single number.', 'Give them three at most, with a trend and a plain sentence each, and refuse the single score politely. A composite number hides the thing that is getting worse inside the thing that is getting better, and the first time it does that in public it stops being believed.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_measure-programme_f2', 'q_grc_mid_measure-programme', 2, 'A metric is improving but you do not believe it.', 'Check what behaviour it created, because people optimise what is measured. Mean time to close drops beautifully when tickets get closed without fixing anything. Validate against the underlying reality by sampling, and change the measure if it has started rewarding the wrong move.');

INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES ('q_grc_mid_soc2-vs-iso', 'grc', 'certification', 'mid', 'Explain SOC 2 and ISO 27001 to a CFO who wants to know which one to pay for.', 'ISO 27001 certifies a management system against an international standard and travels well, especially in Europe and Asia. SOC 2 is an attestation report by an auditor on how your controls operated, and North American customers ask for it by name. The CFO question is not which is better, it is which one your buyers are asking for.', '2026-11-20T03:56:47.918Z');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-vs-iso_f1', 'q_grc_mid_soc2-vs-iso', 1, 'They ask whether doing one makes the other cheap.', 'Cheaper, not cheap. A lot of the underlying evidence overlaps, so the second costs noticeably less than the first, but the framing, scope and auditor work differ. Give them a rough ratio and say it depends on how well the first was scoped, rather than promising a number you will have to walk back.');
INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES ('q_grc_mid_soc2-vs-iso_f2', 'q_grc_mid_soc2-vs-iso', 2, 'They ask whether either means you cannot be breached.', 'No, and say it directly. Both tell a customer that you run a managed programme and that an independent party checked it. Neither is a guarantee, and a certified company can still be breached. Overselling this is how security loses the room the first time something goes wrong.');
